{
  "name": "sample-cli",
  "version": "1.0.0",
  "description": "A tiny text-table CLI used as a throwaway project for E6 replay recordings.",
  "type": "module",
  "bin": { "sample-cli": "src/cli.js" },
  "scripts": { "test": "node --test" }
}
#!/usr/bin/env node
import { parse } from "./parse.js";
import { formatTable } from "./format.js";
import { sortPairs } from "./sort.js";
import { summarize } from "./stats.js";

const args = new Set(process.argv.slice(2));
let input = "";
for await (const chunk of process.stdin) input += chunk;

let pairs = parse(input);
if (args.has("--sort")) pairs = sortPairs(pairs, { byValue: args.has("--by-value") });
console.log(formatTable(pairs));
if (args.has("--summary")) {
  const { count, distinctKeys, longestValue } = summarize(pairs);
  console.log(`\n${count} rows, ${distinctKeys} keys, longest value ${longestValue}`);
}
// Renders pairs as a two-column table.
export function formatTable(pairs) {
  // Bug: tab padding misaligns columns when a key is longer than a tab stop.
  return pairs.map(([key, value]) => `${key}\t${value}`).join("\n");
}
import { tokenize } from "./tokenize.js";

// Parses `key=value` lines into [key, value] pairs.
export function parse(input) {
  return tokenize(input).map((line) => {
    const index = line.indexOf("=");
    return index === -1 ? [line, ""] : [line.slice(0, index), line.slice(index + 1)];
  });
}
// Sorts pairs by key, or by value when byValue is set.
export function sortPairs(pairs, { byValue = false } = {}) {
  const index = byValue ? 1 : 0;
  return [...pairs].sort((left, right) => left[index].localeCompare(right[index]));
}
// Summarises pairs: count, distinct keys and the longest value.
export function summarize(pairs) {
  const keys = new Set(pairs.map(([key]) => key));
  const longest = pairs.reduce((max, [, value]) => Math.max(max, value.length), 0);
  return { count: pairs.length, distinctKeys: keys.size, longestValue: longest };
}
// Splits input into lines of `key=value` tokens.
export function tokenize(input) {
  const tokens = [];
  let current = "";
  for (const char of input) {
    if (char === "\n") {
      tokens.push(current);
      current = "";
    } else {
      current += char;
    }
  }
  if (current.length > 0) tokens.push(current);
  return tokens.filter((token) => token.length > 0);
}
